// Deploy: supabase functions deploy formation-ai
// Optional AI wording/reasoning: supabase secrets set ANTHROPIC_API_KEY=...   (ANTHROPIC_MODEL overrides the default)
// Without a key it still works: pitch layouts are generated by code and recommendations use a rule-based match of
// your available players to each formation. The AI only chooses a formation and writes explanations; it never draws the positions.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
import { activeLangRule, withLang } from '../_shared/lang.ts';

const cors = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type' };
const json = (b: unknown, status = 200) => new Response(JSON.stringify(b), { status, headers: { ...cors, 'Content-Type': 'application/json' } });

// ── deterministic pitch layout from a shape like "4-2-3-1" (y: 0 = opponent goal, 100 = own goal) ──
const XS: Record<number, number[]> = { 1: [50], 2: [35, 65], 3: [20, 50, 80], 4: [12, 37, 63, 88], 5: [8, 29, 50, 71, 92] };
function labelsFor(role: string, c: number, deep: boolean | null): string[] {
  const rep = (s: string) => Array(c).fill(s);
  if (role === 'DEF') return ({ 2: ['CB', 'CB'], 3: ['CB', 'CB', 'CB'], 4: ['LB', 'CB', 'CB', 'RB'], 5: ['LWB', 'CB', 'CB', 'CB', 'RWB'] } as any)[c] ?? rep('CB');
  if (role === 'FWD') return ({ 1: ['ST'], 2: ['ST', 'ST'], 3: ['LW', 'ST', 'RW'] } as any)[c] ?? rep('ST');
  if (deep === true) return ({ 1: ['DM'], 2: ['DM', 'DM'] } as any)[c] ?? rep('CM');
  if (deep === false) return ({ 1: ['AM'], 2: ['AM', 'AM'], 3: ['LW', 'AM', 'RW'] } as any)[c] ?? (c >= 4 ? ['LM', ...Array(c - 2).fill('CM'), 'RM'] : rep('CM'));
  return ({ 1: ['CM'], 2: ['CM', 'CM'], 3: ['CM', 'CM', 'CM'], 4: ['LM', 'CM', 'CM', 'RM'], 5: ['LM', 'CM', 'CM', 'CM', 'RM'] } as any)[c] ?? rep('CM');
}
function layout(shape: string) {
  const lines = shape.split('-').map(Number), n = lines.length;
  const pos: any[] = [{ key: 'GK', label: 'GK', x: 50, y: 92 }];
  const mids = lines.map((_, i) => i).filter((i) => i > 0 && i < n - 1);
  lines.forEach((c, i) => {
    const y = n === 1 ? 45 : Math.round(74 - i * (60 / (n - 1)));
    const role = i === 0 ? 'DEF' : i === n - 1 ? 'FWD' : 'MID';
    const deep = role === 'MID' && mids.length === 2 ? i === mids[0] : null;
    const labs = labelsFor(role, c, deep), xs = XS[c] ?? Array.from({ length: c }, (_, j) => Math.round(12 + (j * 76) / (c - 1)));
    for (let j = 0; j < c; j++) pos.push({ key: `${role[0]}${i + 1}_${j + 1}`, label: labs[j], x: xs[j], y });
  });
  return pos;
}
const OUTFIELD: Record<string, number> = { '11-a-side': 10, '9-a-side': 8, '7-a-side': 6 };
const validShape = (s: string, format: string) => /^\d(-\d){1,4}$/.test(s) && s.split('-').map(Number).reduce((a, b) => a + b, 0) === OUTFIELD[format] && s.split('-').every((x) => +x >= 1);

async function ask(system: string, user: string): Promise<any | null> {
  const key = Deno.env.get('ANTHROPIC_API_KEY'); if (!key) return null;
  try {
    const r = await fetch('https://api.anthropic.com/v1/messages', { method: 'POST', signal: AbortSignal.timeout(20000),
      headers: { 'content-type': 'application/json', 'x-api-key': key, 'anthropic-version': '2023-06-01' },
      body: JSON.stringify({ model: Deno.env.get('ANTHROPIC_MODEL') ?? 'claude-sonnet-5-5', max_tokens: 700, system: system + activeLangRule(), messages: [{ role: 'user', content: user }] }) });
    const txt: string = (await r.json()).content?.[0]?.text ?? '';
    const m = txt.match(/\{[\s\S]*\}/); return m ? JSON.parse(m[0]) : null;
  } catch { return null; }
}
const clip = (s: unknown, n = 600) => String(s ?? '').slice(0, n);

async function design(body: any) {
  const format: string = OUTFIELD[body.format] ? body.format : '11-a-side';
  const prompt = clip(body.prompt, 500);
  const typed = String(body.formation ?? '').trim() || (prompt.match(/\b\d(?:-\d){1,4}\b/)?.[0] ?? '');
  const ai = await ask('You are a football coaching assistant. Reply with JSON only.',
    `Pick ONE formation for a ${format} team (${OUTFIELD[format]} outfield players, goalkeeper not counted) that fits this request: "${prompt || typed || 'a balanced shape'}".` +
    ` The formation must be written as dash-separated line counts that add up to exactly ${OUTFIELD[format]} (example for 11-a-side: "4-3-3").` +
    ` Reply as JSON: {"formation":"...","name":"short name","description":"1-2 sentences","how_to_use":"2-3 sentences on when and how to use it","strengths":"1-2 sentences","weaknesses":"1-2 sentences"}. Do not mention specific players.`);
  let shape = ai?.formation && validShape(ai.formation, format) ? ai.formation : (typed && validShape(typed, format) ? typed : (format === '11-a-side' ? '4-4-2' : format === '9-a-side' ? '3-3-2' : '2-3-1'));
  const lines = shape.split('-').map(Number);
  const text = ai ?? {};
  return {
    name: clip(text.name && ai?.formation === shape ? `${shape} (${text.name})` : shape, 60), format, shape, positions: layout(shape), ai: !!ai,
    description: clip(text.description) || `A ${shape} shape with ${lines[0]} at the back${lines.length > 2 ? `, ${lines.slice(1, -1).join(' and ')} in midfield` : ''} and ${lines[lines.length - 1]} up front.`,
    how_to_use: clip(text.how_to_use) || 'Review how your players fit these roles in training before using it in a match.',
    strengths: clip(text.strengths), weaknesses: clip(text.weaknesses),
  };
}

async function recommend(admin: any, matchId: string) {
  const { data: m } = await admin.from('matches').select('*, opponents(name)').eq('id', matchId).maybeSingle();
  if (!m) throw new Error('Match not found');
  const { data: players } = await admin.from('players').select('id, full_name, positions(name)').eq('is_active', true);
  const { data: av } = await admin.from('match_availability').select('player_id,status').eq('match_id', matchId);
  const out = new Set((av ?? []).filter((a: any) => a.status === 'unavailable').map((a: any) => a.player_id));
  const avail = (players ?? []).filter((p: any) => !out.has(p.id));
  const counts: Record<string, number> = { Goalkeeper: 0, Defender: 0, Midfielder: 0, Forward: 0 };
  avail.forEach((p: any) => { const n = p.positions?.name; if (n && n in counts) counts[n]++; });
  const { data: forms } = await admin.from('formations').select('id,name,format,description').eq('is_active', true).eq('format', '11-a-side');
  const { data: pred } = await admin.from('match_predictions').select('*').eq('match_id', matchId).maybeSingle();
  const shape = (n: string) => n.split('-').map(Number);
  // rule-based fit: compare formation lines to available defenders / midfielders / forwards
  const score = (n: string) => {
    const l = shape(n), d = l[0], f = l[l.length - 1], mid = l.slice(1, -1).reduce((a, b) => a + b, 0);
    const miss = (need: number, have: number) => Math.max(0, need - have) * 3 + Math.max(0, have - need) * 0.3;
    return miss(d, counts.Defender) + miss(mid, counts.Midfielder) + miss(f, counts.Forward);
  };
  const ranked = [...(forms ?? [])].sort((a: any, b: any) => score(a.name) - score(b.name));
  let pick = ranked[0]; let reasoning = `With ${counts.Defender} defenders, ${counts.Midfielder} midfielders and ${counts.Forward} forwards available, ${pick?.name} uses your squad best.`;
  const ai = await ask('You are a football coaching assistant. Reply with JSON only. Use only the data given; do not invent players, injuries or form.',
    `Choose the best formation for ${m.is_home ? 'a home' : 'an away'} match against ${m.opponents?.name}.\nAvailable players by position: ${JSON.stringify(counts)} (${avail.length} total).\n` +
    (pred ? `Our win/draw/loss estimate: ${pred.win_pct}/${pred.draw_pct}/${pred.loss_pct}.\n` : '') +
    `Options: ${(forms ?? []).map((f: any) => `${f.name} — ${f.description}`).join(' | ')}\n` +
    `Reply as JSON: {"formation_name":"<exactly one option name>","reasoning":"2-3 sentences","alternatives":["<option name>","<option name>"]}`);
  if (ai?.formation_name) { const f = (forms ?? []).find((x: any) => x.name === ai.formation_name); if (f) { pick = f; reasoning = clip(ai.reasoning, 700) || reasoning; } }
  const alts = ((ai?.alternatives ?? []) as string[]).filter((n) => (forms ?? []).some((f: any) => f.name === n) && n !== pick?.name).slice(0, 2);
  return { formation_id: pick?.id, name: pick?.name, reasoning, alternatives: alts.length ? alts : ranked.slice(1, 3).map((f: any) => f.name), available: counts, ai: !!ai };
}

Deno.serve(withLang(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  const url = Deno.env.get('SUPABASE_URL')!;
  const caller = createClient(url, Deno.env.get('SUPABASE_ANON_KEY')!, { global: { headers: { Authorization: req.headers.get('Authorization') ?? '' } } });
  const { data: ok } = await caller.rpc('has_permission', { perm: 'lineups.manage' });
  if (!ok) return json({ error: 'Forbidden' }, 403);
  const body = await req.json().catch(() => ({}));
  try {
    if (body.mode === 'design') return json(await design(body));
    if (body.mode === 'recommend') return json(await recommend(createClient(url, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!), String(body.match_id)));
    return json({ error: 'Unknown mode' }, 400);
  } catch (e) { return json({ error: String((e as Error).message ?? e) }, 500); }
}));
